const ee = require('@google/earthengengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon for Smith Island, MD, based on rough coordinates.
  // This is a rough outline and may need refinement for high precision analysis.
  const smithIsland = ee.Geometry.Polygon(
    [[[-76.08, 37.94],
      [-76.08, 37.98],
      [-76.02, 37.98],
      [-76.02, 37.94],
      [-76.08, 37.94]]]
  );

  const startYear1 = '1999-06-01';
  const endYear1 = '1999-09-30'; // Summer/early fall to minimize water level variation

  const startYear2 = '2019-06-01';
  const endYear2 = '2019-09-30'; // Summer/early fall

  const scale = 30; // Landsat resolution

  // 2. Data Acquisition & Pre-processing

  // Cloud mask function for Landsat 5 (C02/T1_SR)
  function maskL5sr(image) {
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Get the QA_PIXEL band.
    const qa = image.select('pixel_qa');
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['B2', 'B5', 'B7']).divide(10000);
  }

  // Cloud mask function for Landsat 8 (C02/T1_SR)
  function maskL8sr(image) {
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Get the QA_PIXEL band.
    const qa = image.select('QA_PIXEL');
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['B3', 'B6', 'B7']).divide(10000);
  }

  // Calculate Modified Normalized Difference Water Index (MNDWI)
  // MNDWI = (Green - SWIR1) / (Green + SWIR1)
  function addMNDWI_L5(image) {
    const mndwi = image.normalizedDifference(['B2', 'B5']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  function addMNDWI_L8(image) {
    const mndwi = image.normalizedDifference(['B3', 'B6']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // Function to calculate land area
  function calculateLandArea(imageCollection, geometry, year, collectionName) {
    let collection = imageCollection
      .filterBounds(geometry)
      .filterDate(year.start, year.end);

    // Apply specific cloud mask and MNDWI function based on collection type
    if (collectionName === 'L5') {
      collection = collection.map(maskL5sr).map(addMNDWI_L5);
    } else if (collectionName === 'L8') {
      collection = collection.map(maskL8sr).map(addMNDWI_L8);
    }

    const image = collection.median();

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${collectionName} in ${year.start}-${year.end}.`);
      return null;
    }

    // Threshold MNDWI to classify land (MNDWI < threshold) and water (MNDWI >= threshold)
    // A common threshold for MNDWI is 0.0 or slightly positive for water.
    // Setting land as pixels where MNDWI is less than a small positive value (e.g., 0.05)
    // to account for mixed pixels and shallow water.
    const mndwiThreshold = 0.05;
    const landMask = image.select('MNDWI').lt(mndwiThreshold).rename('land');

    // Calculate pixel count for validation
    const pixelCount = landMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('land').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels after cloud masking and land classification for ${year.start}-${year.end}.`);
      return null;
    }

    // Calculate land area
    const landAreaImage = landMask.multiply(ee.Image.pixelArea()).divide(1e6); // Area in sq km
    const totalLandArea = landAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('land').getInfo();

    return { area: totalLandArea, imageCount: collectionSize, validPixels: pixelCount };
  }

  // Data for 1999 (Landsat 5)
  const l5Collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR');
  const year1Data = calculateLandArea(l5Collection, smithIsland, { start: startYear1, end: endYear1 }, 'L5');

  if (year1Data === null) {
    if (l5Collection.filterBounds(smithIsland).filterDate(startYear1, endYear1).size().getInfo() === 0) {
      console.log("Empty Collection (no images found for 1999).");
      console.log("C1");
      return;
    } else {
      console.log("No valid pixels for 1999 after processing.");
      console.log("C2");
      return;
    }
  }

  // Data for 2019 (Landsat 8)
  const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR');
  const year2Data = calculateLandArea(l8Collection, smithIsland, { start: startYear2, end: endYear2 }, 'L8');

  if (year2Data === null) {
    if (l8Collection.filterBounds(smithIsland).filterDate(startYear2, endYear2).size().getInfo() === 0) {
      console.log("Empty Collection (no images found for 2019).");
      console.log("C1");
      return;
    } else {
      console.log("No valid pixels for 2019 after processing.");
      console.log("C2");
      return;
    }
  }

  const area1999_sqkm = year1Data.area;
  const area2019_sqkm = year2Data.area;

  // 5. Validation & Final Answer
  if (area1999_sqkm === null || area2019_sqkm === null || isNaN(area1999_sqkm) || isNaN(area2019_sqkm)) {
    console.log("C3"); // Calculation failed
    return;
  }

  console.log(`1999 Images: ${year1Data.imageCount}, Valid Pixels: ${year1Data.validPixels}, Land Area: ${area1999_sqkm.toFixed(2)} km²`);
  console.log(`2019 Images: ${year2Data.imageCount}, Valid Pixels: ${year2Data.validPixels}, Land Area: ${area2019_sqkm.toFixed(2)} km²`);

  if (area2019_sqkm < area1999_sqkm) {
    console.log("A"); // Yes, land area decreased
  } else {
    console.log("B"); // No, land area did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

